// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        (bool success, bytes memory returnData) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        if (success) {
            (bool result) = abi.decode(returnData, (bool));
            assertTrue(result);
        }
    }
}

